 async function importFiles(files,options,u,g){stop();if(!files.length)return;status('Đang nhận diện '+files.length+' file…');let count=0,errors=[];const cursors=new Map(),destinations=new Map();for(const file of files){try{guard(u,g);const kind=mediaKind(file);if(!kind)throw Error('Định dạng không hỗ trợ: '+file.name);if(mode==='image'&&kind!=='image')throw Error('Tab ảnh chỉ nhận PNG, JPG hoặc WebP.');if(kind==='effect'){if(file.size>32768)throw Error('File preset hiệu ứng tối đa 32 KB.');const preset=parseEffect(JSON.parse(await file.text()));guard(u,g);const c=insertEffect(preset,destinations.get(kind)||options.requestedId,options.start,options.forceNew&&!destinations.has(kind));destinations.set(kind,c.trackId);cursors.set(c.trackId,endOf(c));}else{const key=await ingest(file,file.name,u,g,uid(),kind);guard(u,g);const r=resources.get(key);if(mode==='image'){addResource(key);}else{remember();const track=resolveTrack(kind,destinations.get(kind)||options.requestedId,options.forceNew&&!destinations.has(kind));destinations.set(kind,track.id);let start=options.append&&track.id==='base'?Math.max(0,...clips.filter(c=>c.trackId===track.id).map(endOf)):Number(options.start)||0;start=cursors.get(track.id)??start;const c=newClip(r,track.id,start);clips.push(c);cursors.set(track.id,endOf(c));selected=c.id;target=track.id;}}count++;render();}catch(e){if(u!==owner||g!==epoch)throw e;errors.push(e.message);}}await preview();status('Đã nhập '+count+'/'+files.length+' file'+(target?' · '+(tracks.find(t=>t.id===target)?.name||'Thiết kế'):'')+(errors.length?'. '+errors.join(' · '):'.'),count===0&&!!errors.length);}
 function dropInfo(e){const lane=e.target.closest('[data-lane]'),inside=!!e.target.closest('#csTimelineScroll'),ruler=e.target.closest('#csRuler');return{requestedId:lane?.dataset.lane||target,start:inside?atPointer(e):time,forceNew:inside&&!lane&&!ruler,append:false};}
 function isOurDrag(dt){return [...(dt?.types||[])].some(t=>['Files','application/x-fbtq-resource','application/x-fbtq-effect'].includes(t));}
