 root.addEventListener('dragover',e=>{if(!isOurDrag(e.dataTransfer))return;e.preventDefault();if(busy||recording){e.dataTransfer.dropEffect='none';return;}e.dataTransfer.dropEffect='copy';root.classList.add('cs-drop-active');root.querySelectorAll('.cs-drop-target').forEach(el=>el.classList.remove('cs-drop-target'));const lane=e.target.closest('[data-lane]');lane?.classList.add('cs-drop-target');const types=[...e.dataTransfer.items||[]].filter(i=>i.kind==='file').map(i=>i.type.startsWith('audio/')?'âm thanh':i.type.startsWith('image/')?'ảnh':i.type.startsWith('video/')?'video':'file / preset');q('#csDropHint').textContent='Thả để thêm '+([...new Set(types)].join(', ')||'tư liệu / hiệu ứng')+' · Tự chọn lớp phù hợp';q('#csDropHint').hidden=false;});
