 document.addEventListener('keydown',e=>{if(!state.user?.uid||$('#app').classList.contains('hidden')||!root.classList.contains('active')||q('#csShortcutDialog')?.open||document.querySelector('[aria-modal="true"]')||e.target.closest?.('input,textarea,select,[contenteditable]:not([contenteditable="false"]),[role="textbox"]'))return;const name=shortcutAction(e);if(!name)return;if(recording||busy){if(['save','export','import','play','delete'].includes(name))e.preventDefault();return;}if(mode==='image'&&['play','split','splitAll','trimLeft','trimRight','rippleDelete','splitTool'].includes(name))return;e.preventDefault();if(['undo','redo','save','import','export','play','delete'].includes(name))runShortcut(name,who(),epoch).catch(err=>status(err.message,true));else action((u,g)=>runShortcut(name,u,g));});

